const BRANCH_NAMES = {
  "1":   { ko: "1호선 본선 (연천 ↔ 인천)", en: "Line 1 Main (Yeoncheon ↔ Incheon)" },
  "1b":  { ko: "경부·장항선 지선 (구로 ↔ 신창)", en: "Gyeongbu / Cheonan Branch (Guro ↔ Sinchang)" },
  "1c":  { ko: "광명 셔틀 (금천구청 ↔ 광명)", en: "Gwangmyeong Shuttle (Geumcheon-gu Office ↔ Gwangmyeong)" },
  "1d":  { ko: "서동탄 지선 (병점 ↔ 서동탄)", en: "Seodongtan Branch (Byeongjeom ↔ Seodongtan)" },
  "2":   { ko: "2호선 을지로순환선", en: "Line 2 Circle Line" },
  "2n":  { ko: "성수지선 (성수 ↔ 신설동)", en: "Seongsu Branch (Seongsu ↔ Sinseol-dong)" },
  "2s":  { ko: "신정지선 (신도림 ↔ 까치산)", en: "Sinjeong Branch (Sindorim ↔ Kkachisan)" },
  "5":   { ko: "5호선 본선·하남선 (방화 ↔ 하남검단산)", en: "Line 5 Main & Hanam (Banghwa ↔ Hanam Geomdansan)" },
  "5a":  { ko: "하남선 구간 (강동 ↔ 하남검단산)", en: "Hanam Extension (Gangdong ↔ Hanam Geomdansan)" },
  "5b":  { ko: "마천지선 (강동 ↔ 마천)", en: "Macheon Branch (Gangdong ↔ Macheon)" },
  "6":   { ko: "6호선 본선 (응암 ↔ 신내)", en: "Line 6 Main (Eungam ↔ Sinnae)" },
  "6l":  { ko: "응암순환선 (응암 ↔ 구산)", en: "Eungam Loop (Eungam ↔ Gusan)" },
  "G":   { ko: "경의·중앙선 본선 (임진강 ↔ 지평)", en: "Gyeongui-Jungang Main (Imjingang ↔ Jipyeong)" },
  "Gs":  { ko: "경의선 서울역 지선 (가좌 ↔ 서울)", en: "Seoul Station Branch (Gajwa ↔ Seoul Station)" }
};

const LO = Object.keys(D.L).sort((a, b) => D.L[a].o - D.L[b].o);
const ST = D.S.map((s, i) => ({
  i, ko: s[0], en: s[1], ja: s[2], lat: s[3], lng: s[4], ap: s[5], x: s[6], y: s[7],
  cd: { ...s[8] }, aliases: (s[9] || []).slice(), ln: []
}));

// Line-specific display names: ONE station record, several names. Internal index/ID never changes.
const DISPLAY_NAMES = {
  "총신대입구": {
    "4": {
      "ko": "총신대입구(이수)",
      "en": "Chongshin Univ.(Isu)"
    },
    "7": {
      "ko": "이수(총신대입구)",
      "en": "Isu(Chongshin Univ.)"
    }
  },
  "서울역": {
    "GTX-A": {
      "ko": "서울",
      "en": "Seoul"
    }
  }
};
ST.forEach(s => { if (DISPLAY_NAMES[s.ko]) s.displayNames = DISPLAY_NAMES[s.ko]; });

// Connected route sequences (trunks + branches)
const RT = D.R.map(r => ({
  id: r[0], g: r[1], loop: r[2], a: r[3].slice(),
  label: BRANCH_NAMES[r[0]] || { ko: D.L[r[1]].k, en: D.L[r[1]].e }
}));
RT.forEach(r => r.a.forEach(i => { if (!ST[i].ln.includes(r.g)) ST[i].ln.push(r.g); }));
ST.forEach(s => s.ln.sort((a, b) => D.L[a].o - D.L[b].o));

// Ordered unique station list per line (trunk -> branch continuity)
const GS = {};
LO.forEach(g => {
  const seen = new Set(), ordered = [];
  RT.filter(r => r.g === g && r.id !== "5a").forEach(r => r.a.forEach(idx => { if (!seen.has(idx)) { seen.add(idx); ordered.push(idx); } }));
  GS[g] = ordered;
});
